package org.beckenburg;

import java.awt.event.*;
import java.awt.image.BufferedImage;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import javax.imageio.ImageIO;
import javax.swing.*;
import org.beckenburg.editor.*;

/** Actual perspective modeling window gestures, selection and runtime publication. */
public final class AssetImportPerspectiveGuiTest {
    private static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    private static Object field(Object o,String name)throws Exception{var f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
    private static Object call(Object o,String name,Class<?>[] types,Object... args)throws Exception{var m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(o,args);}
    private static Object get(Object o,String name)throws Exception{return call(o,name,new Class<?>[0]);}
    private static double number(Object o,String name)throws Exception{return ((Number)get(o,name)).doubleValue();}
    private static void button(Object o,String name)throws Exception{((JButton)field(o,name)).doClick();}
    private static void event(JPanel canvas,int id,int x,int y,int button){canvas.dispatchEvent(new MouseEvent(canvas,id,System.currentTimeMillis(),id==MouseEvent.MOUSE_DRAGGED?InputEvent.getMaskForButton(button):0,x,y,1,false,id==MouseEvent.MOUSE_DRAGGED?MouseEvent.NOBUTTON:button));}
    private static void drag(JPanel canvas,int button,int x,int y,int dx,int dy){event(canvas,MouseEvent.MOUSE_PRESSED,x,y,button);event(canvas,MouseEvent.MOUSE_DRAGGED,x+dx,y+dy,button);event(canvas,MouseEvent.MOUSE_RELEASED,x+dx,y+dy,button);}
    private static boolean ready(AssetImportDialog ui){try{return !((Boolean)field(ui,"busy"))&&((JButton)field(ui,"apply")).isEnabled();}catch(Exception e){throw new RuntimeException(e);}}
    private static void await(java.util.function.BooleanSupplier condition)throws Exception{long end=System.nanoTime()+30_000_000_000L;while(System.nanoTime()<end){var done=new java.util.concurrent.atomic.AtomicBoolean();SwingUtilities.invokeAndWait(()->done.set(condition.getAsBoolean()));if(done.get())return;Thread.sleep(20);}throw new AssertionError("Perspective human operation did not complete");}
    private static Object viewport(AssetImportDialog ui)throws Exception{return call(ui,"viewport",new Class<?>[]{List.class,int.class,int.class},get(ui,"workingReference"),0,ui.workingViewportWidth());}
    private static EditorMeshPicking.Projector camera(AssetImportDialog ui)throws Exception{return (EditorMeshPicking.Projector)call(ui,"projector",new Class<?>[]{List.class},get(ui,"workingReference"));}
    private static void pickFront(AssetImportDialog ui)throws Exception{var p=camera(ui).project(0,-1d/3,1);var view=viewport(ui);int x=(Integer)call(view,"x",new Class<?>[]{double.class},p.x()),y=(Integer)call(view,"y",new Class<?>[]{double.class},p.y());var canvas=(JPanel)field(ui,"preview");event(canvas,MouseEvent.MOUSE_PRESSED,x,y,1);event(canvas,MouseEvent.MOUSE_RELEASED,x,y,1);check(((EditorMeshPicking.Hit)field(ui,"selectedHit")).faceId()==1,"Human picks actual visible foreground triangle in perspective");}
    public static void main(String[] args)throws Exception{
        Path root=Files.createTempDirectory("human-perspective-");String previous=System.getProperty("user.home");System.setProperty("user.home",root.toString());Path output=Path.of("build/editor-agent-evidence").toAbsolutePath();Files.createDirectories(output);Path source=root.resolve("layers.obj");byte[] original=("o back\nv -1 -1 -1\nv 1 -1 -1\nv 0 1 -1\nv -1 -1 1\nv 1 -1 1\nv 0 1 1\nvt 0 0\nvt 1 0\nvt .5 1\nf 1/1 2/2 3/3\no front\nf 4/1 5/2 6/3\n").getBytes(java.nio.charset.StandardCharsets.UTF_8);Files.write(source,original);
        var ui=new AtomicReference<AssetImportDialog>();var published=new AtomicReference<String>();var project=new AtomicReference<EditorTopologyProject>();var initial=new AtomicReference<EditorTopologyProject.State>();
        try{
            SwingUtilities.invokeAndWait(()->{var dock=new AssetImportDialog(null,published::set);ui.set(dock);try{((JDialog)field(dock,"dialog")).setVisible(true);dock.loadSource(source);}catch(Exception e){throw new RuntimeException(e);}});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();project.set((EditorTopologyProject)field(dock,"topologyProject"));initial.set(project.get().snapshot());var yaw=dock.getClass().getDeclaredField("cameraYaw");yaw.setAccessible(true);yaw.setDouble(dock,0);var pitch=dock.getClass().getDeclaredField("cameraPitch");pitch.setAccessible(true);pitch.setDouble(dock,0);((JComboBox<?>)field(dock,"meshView")).setSelectedItem(EditorMeshPicking.Projection.PERSPECTIVE);((JComboBox<?>)field(dock,"selectionMode")).setSelectedItem("FACE");pickFront(dock);long revision=project.get().revision();var canvas=(JPanel)field(dock,"preview");drag(canvas,3,200,200,20,10);check((Double)field(dock,"cameraYaw")==10&&(Double)field(dock,"cameraPitch")==5,"Actual right-drag orbits model camera");canvas.dispatchEvent(new MouseWheelEvent(canvas,MouseEvent.MOUSE_WHEEL,System.currentTimeMillis(),0,300,200,0,false,MouseWheelEvent.WHEEL_UNIT_SCROLL,1,-2));check((Double)field(dock,"cameraZoom")>1,"Actual wheel zooms perspective");drag(canvas,2,300,200,30,-20);check((Double)field(dock,"cameraPanX")!=0&&(Double)field(dock,"cameraPanY")!=0,"Actual middle-drag pans perspective");pickFront(dock);button(dock,"fitCamera");check((Double)field(dock,"cameraZoom")==1&&(Double)field(dock,"cameraPanX")==0,"Fit resets framing without editing the model");drag(canvas,3,200,200,-20,-10);check(project.get().snapshot()==initial.get()&&project.get().revision()==revision,"Orbit/pan/zoom/fit and selection never create scene edits/history");((JToggleButton)field(dock,"boxSelect")).setSelected(true);((JCheckBox)field(dock,"xraySelect")).setSelected(false);drag(canvas,1,2,2,canvas.getWidth()-4,canvas.getHeight()-4);}catch(Exception e){throw new RuntimeException(e);}});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();check(((Set<?>)field(dock,"selectedVertices")).equals(Set.of(3L,4L,5L)),"Actual perspective visible box excludes hidden native back vertices");((JToggleButton)field(dock,"boxSelect")).setSelected(false);((JComboBox<?>)field(dock,"selectionMode")).setSelectedItem("FACE");pickFront(dock);var handles=(List<?>)get(dock,"gizmoHandles");Object handle=null;for(var h:handles)if(((Number)get(h,"axis")).intValue()==0)handle=h;check(handle!=null,"Actual perspective X gizmo exists");int x=(Integer)get(handle,"x"),y=(Integer)get(handle,"y");double wx=number(handle,"worldX"),wy=number(handle,"worldY"),wz=number(handle,"worldZ"),scale=number(handle,"scale");var cam=(EditorMeshPicking.Projector)get(handle,"camera");var a=cam.project(wx,wy,wz);var b=cam.project(wx+.25,wy,wz);var canvas=(JPanel)field(dock,"preview");int dx=(int)Math.round((b.x()-a.x())*scale),dy=(int)Math.round((b.y()-a.y())*scale);event(canvas,MouseEvent.MOUSE_PRESSED,x,y,1);event(canvas,MouseEvent.MOUSE_DRAGGED,x+dx,y+dy,1);((JDialog)field(dock,"dialog")).getRootPane().getActionMap().get("cancel-axis-drag").actionPerformed(new ActionEvent(canvas,0,"Escape"));event(canvas,MouseEvent.MOUSE_RELEASED,x+dx,y+dy,1);check(project.get().snapshot()==initial.get(),"Actual Escape cancels perspective axis preview without editing native geometry");drag(canvas,1,x,y,dx,dy);}catch(Exception e){throw new RuntimeException(e);}});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();var moved=project.get().snapshot();for(var v:moved.vertices()){var before=initial.get().vertices().stream().filter(q->q.id()==v.id()).findFirst().orElseThrow();check(Math.abs(v.x()-before.x()-(v.id()>=3?.25:0))<1e-9,"Perspective drag changes only selected native face by exact snapped world delta");}button(dock,"undoMesh");check(project.get().snapshot().equals(initial.get()),"Perspective drag is one native undo step");button(dock,"redoMesh");check(project.get().snapshot().equals(moved),"Perspective redo exact");button(dock,"saveMesh");check(EditorTopologyProject.open(project.get().documentPath()).snapshot().equals(moved),"Perspective-edited native file reopens exactly");var content=((JDialog)field(dock,"dialog")).getContentPane();var image=new BufferedImage(content.getWidth(),content.getHeight(),BufferedImage.TYPE_INT_ARGB);var g=image.createGraphics();try{content.printAll(g);}finally{g.dispose();}ImageIO.write(image,"png",output.resolve("human-perspective-model.png").toFile());}catch(Exception e){throw new RuntimeException(e);}});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{button(ui.get(),"apply");}catch(Exception e){throw new RuntimeException(e);}});await(()->published.get()!=null);var expected=project.get().mesh();EditorGlbWriter.validate(expected,ImportedAssetLibrary.read(published.get()));var actual=GlbProps.model(published.get());for(int i=0;i<expected.triangles().size();i++){var t=expected.triangles().get(i);var a=actual.triangles().get(i);var wanted=List.of(t.a(),t.b(),t.c());var got=List.of(a.a(),a.b(),a.c());for(int j=0;j<3;j++)check(Math.abs(wanted.get(j).x()-got.get(j).x())<1e-6&&Math.abs(wanted.get(j).y()-got.get(j).y())<1e-6&&Math.abs(wanted.get(j).z()-got.get(j).z())<1e-6,"Every actual game corner matches perspective-edited native geometry");}check(Arrays.equals(Files.readAllBytes(source),original),"Perspective authoring preserves original source");Files.write(output.resolve("human-perspective-runtime.glb"),ImportedAssetLibrary.read(published.get()));Files.copy(project.get().documentPath(),output.resolve("human-perspective-model.btop"),StandardCopyOption.REPLACE_EXISTING);Files.write(output.resolve("human-perspective-source.obj"),original);System.out.println("PASS human perspective: real camera orbit/pan/zoom/fit, visible picking/box, exact snapped axis drag, native history/save/fresh reopen, actual runtime publication and screenshot");
        }finally{SwingUtilities.invokeAndWait(()->{if(ui.get()!=null)try{((JDialog)field(ui.get(),"dialog")).dispose();}catch(Exception e){throw new RuntimeException(e);}});System.setProperty("user.home",previous);try(var paths=Files.walk(root)){for(var path:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}
    }
}
